export function evalArithmetic(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const precedence = {
    '^': 2,
    '*': 1,
    '/': 1,
    '+': 0,
    '-': 0,
  };

  const tokens = [];
  let currentNumber = '';
  let inQuote = false;

  for (const char of text) {
    if (char === '"') {
      inQuote = !inQuote;
    } else if (!inQuote && (char === ' ' || char.match(/^[0-9\+\-\*\/\^\(\)]$/))) {
      if (char.match(/^[0-9\+\-\*\/\^\(\)]$/)) {
        currentNumber += char;
      } else if (currentNumber !== '') {
        tokens.push(parseFloat(currentNumber));
        currentNumber = '';
      }
      tokens.push(char);
    } else {
      throw new SyntaxError('Invalid character');
    }
  }

  if (currentNumber !== '') {
    tokens.push(parseFloat(currentNumber));
  }

  const operatorStack = [];
  const outputQueue = [];

  for (const token of tokens) {
    if (typeof token === 'number') {
      outputQueue.push(token);
    } else if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack[operatorStack.length - 1] !== '(') {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.pop();
    } else if (token in precedence) {
      while (operatorStack.length > 0 && operatorStack[operatorStack.length - 1] in precedence && precedence[operatorStack[operatorStack.length - 1]] >= precedence[token]) {
        outputQueue.push(operatorStack.pop());
      }
      operatorStack.push(token);
    } else {
      throw new SyntaxError('Invalid token');
    }
  }

  while (operatorStack.length > 0) {
    outputQueue.push(operatorStack.pop());
  }

  const stack = [];

  for (const token of outputQueue) {
    if (typeof token === 'number') {
      stack.push(token);
    } else if (token === '^') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(Math.pow(left, right));
    } else if (token === '*') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left * right);
    } else if (token === '/') {
      const right = stack.pop();
      const left = stack.pop();
      if (right === 0) {
        throw new RangeError('Division by zero');
      }
      stack.push(left / right);
    } else if (token === '+') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left + right);
    } else if (token === '-') {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(left - right);
    }
  }

  if (stack.length !== 1) {
    throw new SyntaxError('Invalid expression');
  }

  return stack[0];
}
